<template><div class="page-shell"><StateMessage v-if="state==='loading'" state="loading" message="正在加载歌单…" /><template v-else-if="playlist"><header class="page-header compact"><div><h1>{{playlist.playlist.name}}</h1><p class="page-subtitle">{{playlist.playlist.description||'私人歌单'}}</p></div></header><form class="inline-form" @submit.prevent="add"><input v-model.number="trackId" type="number" min="1" placeholder="歌曲 ID" aria-label="歌曲 ID" required><button class="primary-button" type="submit"><Plus :size="18"/><span>添加歌曲</span></button></form><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="playlist-tracks"><div v-for="(item,index) in playlist.tracks" :key="item.trackId" class="playlist-track"><span>{{String(index+1).padStart(2,'0')}}</span><router-link :to="`/tracks/${item.trackId}`">歌曲 #{{item.trackId}}</router-link><button class="icon-button light" type="button" aria-label="移出歌单" title="移出歌单" @click="remove(item.trackId)"><Trash2 :size="18"/></button></div><p v-if="!playlist.tracks.length" class="empty-state">歌单里还没有歌曲。</p></div></template><StateMessage v-else state="error" :message="error" /></div></template>
<script>
import { Plus,Trash2 } from 'lucide-vue'; import StateMessage from '../components/StateMessage.vue'; import { library } from '../library/client.js'; import { problemMessage } from '../ui/problem-message.js';
export default {name:'PlaylistView',components:{Plus,StateMessage,Trash2},data:()=>({state:'loading',playlist:null,trackId:null,error:''}),async mounted(){await this.load();},methods:{async load(){try{this.playlist=await library.playlist(Number(this.$route.params.playlistId));this.state='ready';}catch(problem){this.state='error';this.error=problemMessage(problem);}},async add(){try{await library.addTrack(this.playlist.playlist.id,{trackId:Number(this.trackId),sortOrder:this.playlist.tracks.length});await this.load();this.trackId=null;}catch(problem){this.error=problemMessage(problem);}},async remove(trackId){try{await library.removeTrack(this.playlist.playlist.id,trackId);await this.load();}catch(problem){this.error=problemMessage(problem);}}}};
</script>
